//! Frozen original, unique shared and native DATA whole-report comparison.
#[path="../fixtures/original_policies/sfx_original.rs"]mod frozen;
#[path="../fixtures/native-sfx/fixture.rs"]mod fixture;
use crate::{sfx_policy::*,captured_raw_tree_pages::{Policy,Data},captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},captured_reactive_reads::Failure};
use std::{path::Path,sync::Arc,io};
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<Budget>,stop:bool}
impl crate::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{if self.stop{return Ok(false)}for(relative,text)in &self.rows{if !crate::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
struct Text<'a>(&'a Data);impl crate::baseline::SiteText for Text<'_>{fn site_text(&self,rel:&str,line:usize)->String{self.0.sites().iter().zip(self.0.source_text()).find(|(s,_)|s.rel==rel&&s.line as usize==line).expect("actual sound source line").1.clone()}}
fn record(outcome:&crate::policy_finish::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
fn current_path(relative: &str) -> &str {
    match relative {
        "code/__defines/sfx.dm" => "code/defines/host/sfx.dm",
        "code/game/sound_sets.dm" => "code/domains/damage/sound_sets.dm",
        _ => relative,
    }
}

fn current_report_paths(mut report: serde_json::Value) -> serde_json::Value {
    let text = report["text"].as_str().unwrap()
        .replace("code/game/sound_sets.dm", "code/domains/damage/sound_sets.dm");
    report["text"] = text.into();
    report
}

fn pages<'a>(root:&'a Path,budget:&Arc<Budget>,case:usize)->Pages<'a>{let mut rows=Vec::new();for(relative,text)in fixture::files(case){let relative=current_path(relative);if Policy::Sfx.selects_path(relative){let source=dm_preprocess::AcquiredSource::from_original_bytes(text.into_bytes(),());rows.push((relative.to_string(),source.lease().source_text().clone()));}}rows.reverse();Pages{root,rows,budget:Arc::clone(budget),stop:false}}
#[test]fn sfx_complete_original_and_shared_and_native_match_all_quirks_scopes_allow_sites_and_report(){use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/sfx_original.rs"))),"fd9dd4192013e9d8333794386dcaa9651e8c2cce");for case in 0..5{let root=crate::test_scratch::dir(&format!("sfx-original-{case}"));for(relative,text)in fixture::files(case){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,text).unwrap();}let configuration=fixture::configuration(case);let path=root.join("tools/ci/lint_scopes.toml");std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,&configuration).unwrap();let options=crate::run::Options{root:root.clone(),lints:vec![fixture::NAME.into()],raw:true,no_cache:true,..Default::default()};let mut registry=crate::lint::Registry::default();frozen::register(&mut registry);let old=crate::run::Engine::new(registry,options.clone()).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());assert!(expected.internal_error.is_none());let current=crate::test_scratch::dir(&format!("sfx-current-{case}"));for(relative,text)in fixture::files(case){let path=current.join(current_path(relative));std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,text).unwrap();}let path=current.join("tools/ci/lint_scopes.toml");std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,&configuration).unwrap();let mut registry=crate::lint::Registry::default();crate::lints::sys_sfx::register(&mut registry);let shared=crate::run::Engine::new(registry,crate::run::Options{root:current.clone(),..options}).unwrap();let expected_current=current_report_paths(record(&expected));assert_eq!(record(&shared.run_one(shared.reg.lints[0].as_ref())),expected_current);
 if case==0{for rule in ["literal_playsound","literal_sound_var","sfx_string_key","spark_triple"]{assert!(expected.run.sites.iter().any(|s|s.rule==rule),"actual original positive {rule}");}assert!(expected.run.sites.iter().any(|s|s.rel=="maps/sounds.dm"));assert!(!expected.run.sites.iter().any(|s|s.rel.contains(".hidden")||s.rel.contains("unit_tests")||s.rel=="code/game/sound_sets.dm"));assert!(expected.allow_used.iter().any(|a|a.name=="sys_literal_playsound"));assert!(expected.run.sites.iter().any(|s|s.rule=="literal_sound_var"&&old.tree.site_text(&s.rel,s.line as usize).contains("ambient_sound")));assert!(!expected.run.sites.iter().any(|s|s.rule=="literal_sound_var"&&old.tree.site_text(&s.rel,s.line as usize).contains("unused_sound")));}
 let budget=Budget::new(128*1024*1024).unwrap();let config=Config::capture(crate::captured_raw_policy::Configuration::Captured(configuration.as_bytes())).unwrap();let data=crate::captured_raw_tree_pages::collect(&pages(&current,&budget,case),Policy::Sfx,&config,&budget,&||Ok(())).unwrap();assert_eq!(data.sites(),expected.run.sites.as_slice());assert_eq!(data.allow_used(),expected.allow_used.as_slice());assert_eq!(data.notes(),expected.run.notes.as_slice());for(site,text)in data.sites().iter().zip(data.source_text()){assert_eq!(*text,old.tree.site_text(&site.rel,site.line as usize));}let empty=Default::default();let scope=config.borrowed_report_scope(fixture::NAME,"sys").unwrap_or(&empty);let actual=crate::policy_finish::finish_report(Policy::Sfx.metadata(),scope,&Text(&data),crate::lint::Run{sites:data.sites().to_vec(),notes:data.notes().to_vec()},data.allow_used().to_vec(),Default::default(),&current,&None,true,|_,_,_|panic!("Sites has no custom report hook"),|_,_|false);assert_eq!(record(&actual),expected_current);println!("SFX_WHOLE_ORIGINAL_NATIVE={}",serde_json::json!({"case":case,"record":record(&actual)}));}}
#[test]fn sfx_checked_growth_mid_source_io_stopped_eof_and_recovery_preserve_real_failures(){let root=std::env::current_dir().unwrap().join("sfx-source-control");let ample=Budget::new(128*1024*1024).unwrap();let mut called=false;crate::captured_raw_file::with_original_policy_file(&root,&root.join("code/probe.dm"),format!("/proc/probe()\n{}","    playsound(src, ambient_sound, 50)\n".repeat(2048)).into(),0,&ample,&mut|_,views|{let file=views.source_file()?;let denied=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let mut keep=crate::captured_allow_annotations::Operation{budget:&denied,poll:&||Ok(())};let mut temp=crate::captured_allow_annotations::Operation{budget:&ample,poll:&||Ok(())};assert!(matches!(facts_of_using(file,&mut keep,&mut temp),Err(Failure::Operational(ref e))if e.kind()==io::ErrorKind::OutOfMemory));let count=std::cell::Cell::new(0usize);let poll=||{let n=count.get()+1;count.set(n);if n==32{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};let mut keep=crate::captured_allow_annotations::Operation{budget:&ample,poll:&poll};assert!(matches!(facts_of_using(file,&mut keep,&mut temp),Err(Failure::Operational(ref e))if e.raw_os_error()==Some(1450)));assert_eq!(count.get(),32);let mut keep=crate::captured_allow_annotations::Operation{budget:&ample,poll:&||Ok(())};let facts=facts_of_using(file,&mut keep,&mut temp)?;let ctx=merge([(file.rel.as_str(),&facts)],&mut keep)?;let denied=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let mut keep=crate::captured_allow_annotations::Operation{budget:&denied,poll:&||Ok(())};let positive=crate::tree::SourceFile::from_text("code/positive.dm","    playsound(src, 'sound/a.ogg', 50)\n");assert!(matches!(scan_file_using(&positive,&ctx,&mut Vec::new(),&mut keep,&mut temp),Err(Failure::Operational(ref e))if e.kind()==io::ErrorKind::OutOfMemory));called=true;Ok(true)}).unwrap();assert!(called);let config=Config::capture(crate::captured_raw_policy::Configuration::Captured(fixture::CONFIG.as_bytes())).unwrap();let mut source=pages(&root,&ample,0);source.stop=true;assert!(matches!(crate::captured_raw_tree_pages::collect(&source,Policy::Sfx,&config,&ample,&||Ok(())),Err(Failure::Unsupported(message))if message.contains("EOF")));source.stop=false;assert!(!crate::captured_raw_tree_pages::collect(&source,Policy::Sfx,&config,&ample,&||Ok(())).unwrap().sites().is_empty());}
